head.script:
scwin.onpageload = function() {

        grid1.setData(["가", 5, "서울", 12,
        			   "나", 4, "인천", 34,
        			   "다", 8, "대구", 64,
        			   "라", 1, "부산", 23
        			   ]);

}        



		scwin.checkVal = function() {
			const checked1 = WebSquare.wUnit.getDomById('grid1_cell_0_0').querySelector('input').getAttribute('checked')
			const checked2 = WebSquare.wUnit.getDomById('grid1_cell_1_0').querySelector('input').getAttribute('checked')
			const checked3 = WebSquare.wUnit.getDomById('grid1_cell_2_0').querySelector('input').getAttribute('checked')
			const checked4 = WebSquare.wUnit.getDomById('grid1_cell_3_0').querySelector('input').getAttribute('checked')
			return checked1 == '' && checked2 == '' && checked3 == '' && checked4 == '';

		};
		scwin.unitTest = function() {
			//Unit test
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_column7').querySelector('input').click()");
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
			WebSquare.wUnit.addCommand("pause", "500");			
			//Run and Stop test
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}	
scwin.unitTest();
